export default {
  name: 'LogoutConfirmationDialog',
  props: {
    modelValue: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      loading: false
    };
  },
  computed: {
    dialog: {
      get() {
        return this.modelValue;
      },
      set(value) {
        this.$emit('update:modelValue', value);
      }
    }
  },
  methods: {
    cancelLogout() {
      this.dialog = false;
      this.$emit('cancel');
    },
    async confirmLogout() {
      this.loading = true;
      try {
        // Emit the confirm event to parent component
        this.$emit('confirm');
        this.dialog = false;
      } catch (error) {
        console.error('Logout error:', error);
      } finally {
        this.loading = false;
      }
    }
  }
};
